from durationkit import parse_duration
valid = {'90': 90.0, ' 90 ': 90.0, '2d': 172800.0, '3h': 10800.0, '15m': 900.0, '45s': 45.0, '500ms': 0.5, '1h30m': 5400.0, '2d4h': 187200.0, '1m1s': 61.0, '1s500ms': 1.5, '1d1h1m1s1ms': 90061.001, ' 1h 30m ': 5400.0, '0s': 0.0, '0': 0.0}
for value, expected in valid.items():
    result = parse_duration(value)
    assert isinstance(result, float) and abs(result - expected) < 1e-9, (value, result)
invalid = ['', '   ', '-1h', '1.5h', '1x', '1h1h', '30m1h', 'h', '1h30', 'abc', '1 h', '1ms1s', '1m1ms1s', '1h 30', '1sfoo', '1Ⅳh', '①h']
for value in invalid:
    try:
        parse_duration(value)
    except ValueError:
        pass
    else:
        raise AssertionError(f'Expected ValueError: {value!r}')
for value in (90, None):
    try:
        parse_duration(value)
    except TypeError:
        pass
    else:
        raise AssertionError(f'Expected TypeError: {value!r}')
print('Contract cases passed')
